//! File-type icons from the Seti UI theme (the VS Code / Cursor default).
//! The table is generated by `script/gen-file-icons`.

mod table;

use gpui::{Hsla, SharedString, rgb};

pub(crate) enum Match {
    EndsWith(&'static str),
    Contains(&'static str),
}

#[derive(Clone, Copy)]
pub(crate) enum IconColor {
    Blue,
    Grey,
    GreyLight,
    Green,
    Ignore,
    Orange,
    Pink,
    Purple,
    Red,
    White,
    Yellow,
}

type Rule = (Match, &'static str, IconColor);

impl IconColor {
    /// Seti's colors are tuned for dark backgrounds; light mode uses
    /// slightly darker variants so they keep their contrast.
    fn hsla(self, is_dark: bool) -> Hsla {
        use IconColor::*;
        let (dark, light) = match self {
            Blue => (0x519aba, 0x498ba7),
            Grey => (0x4d5a5e, 0x455155),
            GreyLight => (0x6d8086, 0x627379),
            Green => (0x8dc149, 0x7fae42),
            Ignore => (0x41535b, 0x3b4b52),
            Orange => (0xe37933, 0xcc6d2e),
            Pink => (0xf55385, 0xdd4b78),
            Purple => (0xa074c4, 0x9068b0),
            Red => (0xcc3e44, 0xb8383d),
            White => (0xd4d7d6, 0x7f8789),
            Yellow => (0xcbcb41, 0xb2b23a),
        };
        rgb(if is_dark { dark } else { light }).into()
    }
}

#[derive(Clone)]
pub struct FileIcon {
    /// Asset path for `svg().path(...)`.
    pub path: SharedString,
    pub color: Hsla,
}

/// Types Seti doesn't know, checked before its table.
static EXTRA_RULES: &[Rule] = &[
    (Match::EndsWith(".mdc"), "markdown", IconColor::Blue),
    // Tables that open like CSV.
    (Match::EndsWith(".tsv"), "csv", IconColor::Green),
    (Match::EndsWith(".psv"), "csv", IconColor::Green),
];

/// The icon for a file name. As in Seti's stylesheet, the last matching
/// rule wins, so `README.md` beats `.md`.
pub fn for_name(name: &str, is_dark: bool) -> FileIcon {
    let (icon, color) = EXTRA_RULES
        .iter()
        .chain(table::RULES.iter().rev())
        .find(|(pattern, _, _)| match pattern {
            Match::EndsWith(s) => name.ends_with(s),
            Match::Contains(s) => name.contains(s),
        })
        .map(|(_, icon, color)| (*icon, *color))
        .unwrap_or(("default", IconColor::White));
    FileIcon {
        path: format!("file-icons/{icon}.svg").into(),
        color: color.hsla(is_dark),
    }
}

/// SVG bytes for an asset path like `file-icons/rust.svg`.
pub fn asset(path: &str) -> Option<&'static [u8]> {
    let icon = path.strip_prefix("file-icons/")?.strip_suffix(".svg")?;
    table::svg(icon)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn icon(name: &str) -> String {
        for_name(name, true).path.to_string()
    }

    #[test]
    fn common_types() {
        assert_eq!(icon("VISION.md"), "file-icons/markdown.svg");
        assert_eq!(icon("README.md"), "file-icons/info.svg");
        assert_eq!(icon("assumptions.json"), "file-icons/json.svg");
        assert_eq!(icon("growth_model.py"), "file-icons/python.svg");
        assert_eq!(icon("main.rs"), "file-icons/rust.svg");
        assert_eq!(icon("Dockerfile"), "file-icons/docker.svg");
        assert_eq!(icon("rules.mdc"), "file-icons/markdown.svg");
        assert_eq!(icon("unknown.zzz"), "file-icons/default.svg");
    }

    #[test]
    fn every_icon_is_embedded() {
        for (_, icon, _) in table::RULES {
            assert!(table::svg(icon).is_some(), "{icon} missing");
        }
        assert!(asset("file-icons/default.svg").is_some());
    }
}
